#include <ctime>
using namespace std;
// Function to check if a number is prime
bool is_prime(int n) {
    if (n <= 1) {
        return false;
    }
    for (int i = 2; i <= sqrt(n); i++) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
}
// Function to generate a random irrational variable
double random_irrational() {
    int choice = rand() % 2;
    if (choice == 0) {
        return M_PI;
    } else {
        return M_E;
    }
}
// Function to generate a random mathematical expression using irrational variables
string random_expression(int num_irrational) {
    vector<string> operators = {"+", "-", "*", "/", "sin", "cos", "tan", "log"};
    string expression = "";
    for (int i = 0; i < num_irrational; i++) {
        expression += to_string(random_irrational());
        if (i < num_irrational - 1) {
            expression += " " + operators[rand() % operators.size()] + " ";
        }
    }
    return expression;
}
// Function to evaluate a mathematical expression
double evaluate_expression(string expression) {
    vector<string> tokens;
    string token = "";
    for (char c : expression) {
        if (c == ' ') {
            tokens.push_back(token);
            token = "";
        } else {
            token += c;
        }
    }
    tokens.push_back(token);
    vector<double> stack;
    for (string token : tokens) {
        if (token == "+") {
            double b = stack.back();
            stack.pop_back();
            double a = stack.back();
            stack.pop_back();
            stack.push_back(a + b);
        } else if (token == "-") {
            double b = stack.back();
            stack.pop_back();
            double a = stack.back();
            stack.pop_back();
            stack.push_back(a - b);
        } else if (token == "*") {
            double b = stack.back();
            stack.pop_back();
            double a = stack.back();
            stack.pop_back();
            stack.push_back(a * b);
        } else if (token == "/") {
            double b = stack.back();
            stack.pop_back();
            double a = stack.back();
            stack.pop_back();
            stack.push_back(a / b);
        } else if (token == "sin") {
            double a = stack.back();
            stack.pop_back();
            stack.push_back(sin(a));
        } else if (token == "cos") {
            double a = stack.back();
            stack.pop_back();
            stack.push_back(cos(a));
        } else if (token == "tan") {
            double a = stack.back();
            stack.pop_back();
            stack.push_back(tan(a));
        } else if (token == "log") {
            double b = stack.back();
            stack.pop_back();
            double a = stack.back();
            stack.pop_back();
            stack.push_back(log(a) / log(b));
        } else {
            stack.push_back(stod(token));
        }
    }
    return stack.back();
}
// Function to generate a puzzle
void generate_puzzle(int num_irrational, vector<char> allowed_operators) {
    int target = rand() % 100 + 1;
    while (!is_prime(target)) {
        target = rand() % 100 + 1;
    }
    cout << "Target: " << target << endl;
    cout << "Irrational variables: ";
    for (int i = 0; i < num_irrational; i++) {
        cout << random_irrational() << " ";
    }
    cout << endl;
    cout << "Allowed operators: ";
    for (char op : allowed_operators) {
        cout << op << " ";
    }
    cout << endl;
    vector<string> expressions;
    for (int i = 0; i < pow(allowed_operators.size(), num_irrational - 1); i++) {
        string expression = random_expression(num_irrational);
        bool valid = true;
        for (char op : allowed_operators) {
            if (expression.find(op) == string::npos) {
                valid = false;
                break;
            }
        }
        if (valid) {
            expressions.push_back(expression);
        }
    }
    sort(expressions.begin(), expressions.end(), [](string a, string b) {
        return evaluate_expression(a) < evaluate_expression(b);
    });
    string solution = "";
    int min_irrational = num_irrational;
    for (string expression : expressions) {
        if (evaluate_expression(expression) == target) {
            solution = expression;
            break;
        } else if (evaluate_expression(expression) > target) {
            int num_irrational_used = count(expression.begin(), expression.end(), 'π') + count(expression.begin(), expression.end(), 'e');
            if (num_irrational_used < min_irrational) {
                solution = expression;
                min_irrational = num_irrational_used;
            }
        }
    }
    if (solution != "") {
        cout << "Solution: " << solution << endl;
    } else {
        cout << "No solution found" << endl;
    }
}
int main() {
    srand(time(NULL));
    vector<char> allowed_operators = {'+', '-', '*', '/', 's', 'c', 't', 'l'};
    generate_puzzle(3, allowed_operators);
    return 0;
}
```
