using namespace std;
int main()
{
    int digits[10] = {0}; // initialize array to keep track of used digits
    int code = 0;
    srand(time(0));

    do {
        // generate random digits
        int digit1 = rand() % 9 + 1; // first digit cannot be 0
        int digit2 = rand() % 10;
        int digit3 = rand() % 10;
        int digit4 = rand() % 10;

        // check if digits are unique
        if (digit1 != digit2 && digit1 != digit3 && digit1 != digit4 && 
            digit2 != digit3 && digit2 != digit4 && digit3 != digit4) {

            // check if digits have not been used before
            if (digits[digit1] == 0 && digits[digit2] == 0 && 
                digits[digit3] == 0 && digits[digit4] == 0) {

                // mark digits as used
                digits[digit1] = 1;
                digits[digit2] = 1;
                digits[digit3] = 1;
                digits[digit4] = 1;

                // concatenate digits to form code
                code = digit1 * 1000 + digit2 * 100 + digit3 * 10 + digit4;
            }
        }
    } while (code == 0); // repeat until a valid code is generated

    cout << "Random 4-digit code: " << code << endl;
    return 0;
}
