    } elseif ($age >= 23.147 && $age < 29.53) {
        $phase = 'Waning Crescent';
    } elseif ($age >= 29.53) {
        $phase = 'New Moon';
    }
    return $phase;
}
function getMoonAge($year, $month, $day) {
