    $IP = ($JDN - 2451550.1) / 29.530588853;
    $IP = $IP - floor($IP);
    $ag = $IP * 29.53;
    if ($ag < 0) {
        $ag = $ag + 29.53;
    }
    return $ag;
}
function getSunEclipticLongitude($year, $month, $day) {
    $jd = gregoriantojd($month, $day, $year);
    $t = ($jd - 2451545.0) / 36525;
    $w = 282.9404 + 4.70935E-5 * $jd;
    $e = 0.016709 - 1.151E-9 * $jd;
    $M = 356.0470 + 0.9856002585 * $jd;
    $L = $w + $M;
    $C = ($e * 180 / pi()) * sin(deg2rad($M));
    $O = 125.04 - 1934.136 * $t;
    $sunLong = $L + $C - $O;
    if ($sunLong > 360) {
        $sunLong = $sunLong - 360;
    } elseif ($sunLong < 0) {
        $sunLong = $sunLong + 360;
    }
    return $sunLong;
}
function getMoonEclipticLongitude($year, $month, $day) {
    $jd = gregoriantojd($month, $day, $year);
    $t = ($jd - 2451545.0) / 36525;
    $L1 = 218.3161 + 481267.8813 * $t;
    $D = 297.8502 + 445267.1115 * $t;
    $M = 357.5291 + 35999.0503 * $t;
    $M1 = 134.9634 + 477198.8675 * $t;
    $F = 93.2721 + 483202.0175 * $t;
    $A1 = 119.75 + 131.849 * $t;
    $A2 = 53.09 + 479264.290 * $t;
    $A3 = 313.45 + 481266.484 * $t;
    $E = 1 - 0.002516 * $t - 0.0000074 * $t * $t;
    $L2 = $L1 + 6.2887 * sin(deg2rad($M1)) + 1.2740 * sin(deg2rad(2 * $D - $M1)) + 0.6583 * sin(deg2rad(2 * $D)) + 0.2136 * sin(deg2rad(2 * $M1)) - $E * 0.1859 * sin(deg2rad($M)) - 0.1143 * sin(deg2rad(2 * $F));
    $D2 = $D - 6.41 * sin(deg2rad($M1)) + 0.21 * sin(deg2rad(2 * $D - $M1)) - 0.19 * sin(deg2rad(2 * $D)) + 0.11 * sin(deg2rad($M1));
    $M2 = $M - 0.9333 * sin(deg2rad(2 * $D - $M1)) - 0.0296 * sin(deg2rad(2 * $D)) + 0.0278 * sin(deg2rad(2 * $M1)) + $E * 0.0192 * sin(deg2rad($M));
    $F2 = $F + 0.0028 * sin(deg2rad(2 * $D - $M1)) + 0.0004 * sin(deg2rad(2 * $D)) - 0.0003 * sin(deg2rad($M1));
    $A4 = 325 * sin(deg2rad($A1));
    $A5 = 165 * sin(deg2rad($A2));
    $A6 = 164 * sin(deg2rad($A3));
    $A7 = 126 * sin(deg2rad($D2 - $F2 - 2 * $A1));
    $A8 = 110 * sin(deg2rad($D2 - $F2 - $A1));
    $moonLong = $L2 + $A4 + $A5 + $A6 - $A7 - $A8;
    if ($moonLong > 360) {
        $moonLong = $moonLong - 360;
    } elseif ($moonLong < 0) {
        $moonLong = $moonLong + 360;
    }
    return $moonLong;
}
function getMoonIllumination($year, $month, $day) {
    $sunLong = getSunEclipticLongitude($year, $month, $day);
    $moonLong = getMoonEclipticLongitude($year, $month, $day);
    $moonPhase = ($moonLong - $sunLong) / 360;
    if ($moonPhase < 0) {
        $moonPhase = $moonPhase + 1;
    }
    $moonIllumination = (1 - cos(deg2rad($moonPhase * 360))) / 2;
