function isPrime($num) {
    if ($num == 2 || $num == 3) {
        return true;
    }
    if ($num % 2 == 0 || $num % 3 == 0) {
        return false;
    }
    $i = 5;
    $w = 2;
    while ($i * $i <= $num) {
        if ($num % $i == 0) {
            return false;
        }
        $i += $w;
        $w = 6 - $w;
    }
    return true;
}
function findNthPrime($n) {
    $count = 0;
    $num = 1001;
    while ($count < $n) {
        if ($num % 3 != 0 && isPrime($num)) {
            $count++;
        }
        $num++;
    }
    return $num - 1;
}
