```c++
#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <cmath>
#include <algorithm>
using namespace std;
// Define a struct to represent a restaurant
struct Restaurant {
    string name;
    string cuisine;
    vector<string> menu;
    double rating;
};
// Define a function to calculate the cosine similarity between two vectors
double cosine_similarity(const vector<double>& v1, const vector<double>& v2) {
    double dot_product = 0.0;
    double norm_v1 = 0.0;
    double norm_v2 = 0.0;
    for (size_t i = 0; i < v1.size(); i++) {
        dot_product += v1[i] * v2[i];
        norm_v1 += pow(v1[i], 2);
        norm_v2 += pow(v2[i], 2);
    }
    return dot_product / (sqrt(norm_v1) * sqrt(norm_v2));
}
// Define a function to find the k-nearest neighbors of a given vector
vector<size_t> k_nearest_neighbors(const vector<vector<double>>& vectors, const vector<double>& query, size_t k) {
    vector<pair<double, size_t>> similarities;
    for (size_t i = 0; i < vectors.size(); i++) {
        double similarity = cosine_similarity(vectors[i], query);
        similarities.push_back(make_pair(similarity, i));
    }
    sort(similarities.rbegin(), similarities.rend());
    vector<size_t> neighbors;
    for (size_t i = 0; i < k; i++) {
        neighbors.push_back(similarities[i].second);
    }
    return neighbors;
}
int main() {
    // Define a database of restaurants
    vector<Restaurant> database = {
        {"Taco Bell", "Mexican", {"Tacos", "Burritos", "Nachos"}, 3.5},
        {"Chipotle", "Mexican", {"Burritos", "Bowls", "Tacos"}, 4.0},
        {"Qdoba", "Mexican", {"Burritos", "Tacos", "Quesadillas"}, 3.8},
        {"Moe's Southwest Grill", "Mexican", {"Burritos", "Tacos", "Nachos"}, 3.7},
        {"Chuy's", "Mexican", {"Tacos", "Enchiladas", "Fajitas"}, 4.2},
        {"Torchy's Tacos", "Mexican", {"Tacos", "Queso", "Guacamole"}, 4.4},
        {"Cafe Rio", "Mexican", {"Burritos", "Tacos", "Enchiladas"}, 4.1},
        {"Baja Fresh", "Mexican", {"Burritos", "Tacos", "Quesadillas"}, 3.6},
        {"El Pollo Loco", "Mexican", {"Tacos", "Burritos", "Quesadillas"}, 3.9},
        {"Rubio's Coastal Grill", "Mexican", {"Tacos", "Burritos", "Salads"}, 4.3}
    };
    // Define a vector of user preferences
    vector<string> preferences = {"Mexican", "Vegetarian", "Gluten-free"};
    // Create a map of menu options to their indices in the vector of user preferences
    unordered_map<string, size_t> menu_indices;
    for (size_t i = 0; i < preferences.size(); i++) {
        menu_indices[preferences[i]] = i;
    }
    // Create a vector of menu vectors, where each vector represents the presence of a menu option in the restaurant's menu
    vector<vector<double>> menu_vectors;
    for (const Restaurant& restaurant : database) {
        vector<double> menu_vector(preferences.size(), 0.0);
        for (const string& item : restaurant.menu) {
            if (menu_indices.count(item) > 0) {
                menu_vector[menu_indices[item]] = 1.0;
            }
        }
        menu_vectors.push_back(menu_vector);
    }
    // Create a vector of ratings
    vector<double> ratings;
    for (const Restaurant& restaurant : database) {
        ratings.push_back(restaurant.rating);
    }
    // Find the k-nearest neighbors of the user preferences
    vector<size_t> neighbors = k_nearest_neighbors(menu_vectors, vector<double>(preferences.size(), 1.0), 3);
    // Output the recommended restaurants
    cout << "Recommended restaurants:" << endl;
    for (size_t neighbor : neighbors) {
        cout << database[neighbor].name << " (" << database[neighbor].cuisine << ", ";
        for (const string& item : database[neighbor].menu) {
            cout << item << ", ";
        }
        cout << "Rating: " << database[neighbor].rating << ")" << endl;
    }
    return 0;
}
```
In this code, we define a struct `Restaurant` to represent a restaurant, and a function `cosine_similarity` to calculate the cosine similarity between two vectors. We also define a function `k_nearest_neighbors` to find the k-nearest neighbors of a given vector.
We then define a database of restaurants, a vector of user preferences, and a map of menu options to their indices in the vector of user preferences. We create a vector of menu vectors, where each vector represents the presence of a menu option in the restaurant's menu, and a vector of ratings.
Finally, we find the k-nearest neighbors of the user preferences using the `k_nearest_neighbors` function, and output the recommended restaurants based on the neighbors' indices in the database.

