```csharp
using System;
using System.Net;
using System.Net.Mail;
class Program
{
    static void Main(string[] args)
    {
        // Set up email credentials
        string fromAddress = "yourEmailAddress@gmail.com";
        string password = "yourPassword";
        string smtpServer = "smtp.gmail.com";
        int smtpPort = 587;
        // Set up message content
        string subject = "Good luck on your exam!";
        string body = "Dear [StudentName],\n\nGood luck on your exam today in [AreaOfStudy]! We know it's going to be tough with the ongoing construction noise, but we believe in you. You got this!\n\nBest,\n[YourName]";
        // Set up list of recipients with their names and areas of study
        string[,] recipients = new string[,] { { "John Smith", "Mathematics" }, { "Jane Doe", "History" }, { "Bob Johnson", "Chemistry" } };
        // Send message to each recipient
        for (int i = 0; i < recipients.GetLength(0); i++)
        {
            // Personalize message with recipient's name and area of study
            string personalizedBody = body.Replace("[StudentName]", recipients[i, 0]).Replace("[AreaOfStudy]", recipients[i, 1]);
            // Set up email message
            MailMessage message = new MailMessage(fromAddress, recipients[i, 0] + "@example.com", subject, personalizedBody);
            // Set up SMTP client
            SmtpClient client = new SmtpClient(smtpServer, smtpPort);
            client.EnableSsl = true;
            client.Credentials = new NetworkCredential(fromAddress, password);
            // Send email
