    public Monkey(int hungerLevel, string foodPreference)
    {
        this.hungerLevel = hungerLevel;
        this.foodPreference = foodPreference;
    }
    public void Eat(List<string> availableFoods)
    {
        Console.WriteLine("Monkey is hungry and looking for food...");
        int preferredFoodIndex = availableFoods.IndexOf(foodPreference);
        if (preferredFoodIndex != -1)
        {
            Console.WriteLine($"Monkey found {foodPreference} and is eating it...");
            availableFoods.RemoveAt(preferredFoodIndex);
            hungerLevel -= 10;
        }
        else
        {
            Console.WriteLine($"Monkey couldn't find {foodPreference} and is choosing another food...");
            string chosenFood = availableFoods[0];
            Console.WriteLine($"Monkey found {chosenFood} and is eating it...");
            availableFoods.RemoveAt(0);
            hungerLevel -= 5;
        }
        Console.WriteLine($"Monkey's hunger level is now {hungerLevel}.");
        if (hungerLevel > 0)
        {
            Eat(availableFoods);
        }
        else
        {
            Console.WriteLine("Monkey is full and stops eating.");
        }
    }
}
