  echo file_get_contents($cacheFile); // Serve from cache
} else {
  $data = getData(); // Function to fetch data
  file_put_contents($cacheFile, $data); // Cache the data
  echo $data;
}
// Minification
ob_start('sanitize_output');
function sanitize_output($buffer) {
  $search = array('/\>[^\S ]+/s', '/[^\S ]+\</s', '/(\s)+/s');
  $replace = array('>', '<', '\\1');
  $buffer = preg_replace($search, $replace, $buffer);
  return $buffer;
}
// Compression
if(!ob_start('ob_gzhandler')) ob_start();
?>
By using these techniques, you can significantly improve the speed, accessibility, and user experience of your web page.

